@startuml

class GasStation {
  + ID : string
  + Address : string
}

class FuelPump {
  + PumpNumber : int
  + IsSelfService : boolean
}

class Fuel {
  + Name : string
  + OctaneRating : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : float
}

class FuelPurchase {
  + PurchaseID : string
  + LitersDispensed : float
}

GasStation "1" *-- "1..12" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "1" -- "*" FuelPurchase
Fuel "1" -- "*" DailyPrice
Fuel "1" -- "*" FuelPurchase
DailyPrice "1" -- "1" Fuel
DailyPrice "1" -- "1" GasStation
FuelPurchase "1" -- "1" FuelPump
FuelPurchase "1" -- "1" DailyPrice

@enduml

